package config

import (
	"strings"
	"testing"
)

func TestParse(t *testing.T) {
	src := "bind 0.0.0.0\n" +
		"port 6399\n" +
		"appendonly yes\n" +
		"peers a,b"
	p := parse(strings.NewReader(src))
	if p == nil {
		t.Error("cannot get result")
		return
	}
	if p.Bind != "0.0.0.0" {
		t.Error("string parse failed")
	}
	if p.Port != 6399 {
		t.Error("int parse failed")
	}
	if !p.AppendOnly {
		t.Error("bool parse failed")
	}
}

func TestParseBooleanValues(t *testing.T) {
	// Test various true values
	trueValues := []string{"yes", "true", "1", "on"}
	for _, trueValue := range trueValues {
		src := "appendonly " + trueValue
		p := parse(strings.NewReader(src))
		if p == nil {
			t.Error("cannot get result")
			return
		}
		if !p.AppendOnly {
			t.Errorf("bool parse failed for value '%s'", trueValue)
		}
	}

	// Test various false values
	falseValues := []string{"no", "false", "0", "off", "anything_else"}
	for _, falseValue := range falseValues {
		src := "appendonly " + falseValue
		p := parse(strings.NewReader(src))
		if p == nil {
			t.Error("cannot get result")
			return
		}
		if p.AppendOnly {
			t.Errorf("bool parse failed for value '%s'", falseValue)
		}
	}
}
